  const big = slowFile([todo('a1'), todo('a2'), todo('a3')]);
  const first = pick(big);
  await pick(quickFile([todo('b1')]));
  await settle();
  assert.deepEqual(replaced, [['b1']], 'the small file fills the empty list without asking');

  big.finish();
  await settle();
  assert.equal(dialog.open, true, 'the big file must ask before replacing a non-empty list');
  assert.deepEqual(replaced, [['b1']], 'nothing is replaced before the customer answers');

  dialog.close('no');
  await first;
  assert.deepEqual(replaced, [['b1']], 'cancel keeps the list');
});

test('a todo added while a file is being read is not replaced without asking', async () => {
  const { pick, submit, replaced, dialog } = loadApp();
  const big = slowFile([todo('a1')]);
  const first = pick(big);
  submit('Mua sữa');

  big.finish();
  await settle();
  assert.equal(dialog.open, true, 'the import must ask: the list is no longer empty');
  assert.deepEqual(replaced, []);

  dialog.close('yes');
  await first;
  assert.deepEqual(replaced, [['a1']], 'agree replaces');
});

test('two imports waiting at once never open the dialog twice', async () => {
  const { pick, submit, replaced, dialog } = loadApp();
  submit('Mua sữa');
  const big = slowFile([todo('a1')]);
  const first = pick(big);
  const second = pick(quickFile([todo('b1')]));
  big.finish();
  await settle();
  assert.equal(dialog.open, true);

  dialog.close('no');
  await settle();
  assert.equal(dialog.open, true, 'the next import asks once the first dialog is closed');
  dialog.close('yes');
  await Promise.all([first, second]);
  assert.equal(replaced.length, 1);
});

