// Bug report: the customer picks a big backup file, then, while it is still being read, a second, smaller one. The small
// file fills the empty list; when the big one finishes it replaced that list without the confirm dialog. Importing must
// never replace a non-empty list without asking. app.js runs unchanged in a vm context, as in app.test.js. Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const backup = require('../app/backup.js');

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');

function fakeElement() {
  const listeners = {};
  const el = {
    textContent: '', innerHTML: '', hidden: false, value: '', className: '', dataset: {}, returnValue: '', open: false,
    append() {},
    querySelector(sel) { return (el.children[sel] ||= fakeElement()); },
    children: {},
    addEventListener(type, fn) { (listeners[type] ||= []).push(fn); },
    showModal() {
      if (el.open) throw new Error('InvalidStateError: dialog already open');
      el.open = true;
    },
    close(value) {
      el.open = false;
      el.returnValue = value;
      const fns = listeners.close || [];
      listeners.close = [];
      fns.forEach((fn) => fn());
    },
  };
  return el;
}

// A file whose text() resolves only when the test says so, like a big file still being read.
function slowFile(todos) {
  let finish;
  const done = new Promise((resolve) => { finish = resolve; });
  const text = JSON.stringify({ version: 1, todos });
  return { size: text.length, text: () => done.then(() => text), finish };
}

function quickFile(todos) {
  const text = JSON.stringify({ version: 1, todos });
  return { size: text.length, text: async () => text };
}

const todo = (id) => ({ id, title: `Việc ${id}`, done: false, createdAt: 1 });
const settle = () => new Promise((resolve) => setImmediate(resolve));

// The fake store knows whether the list it holds is non-empty, and records a violation whenever replace() overwrites a
// non-empty list without a "yes" from the dialog since the last write.
function loadApp() {
  const elements = {};
  const replaced = [];
  const violations = [];
  let held = 0;
  let approved = false;
  const store = {
    readError: false,
    load() { return { todos: [], readError: false }; },
    save(todos) { held = todos.length; return 'saved'; },
    replace(todos) {
      if (held > 0 && !approved) violations.push(`replaced ${held} todos with ${todos.length} without asking`);
      approved = false;
      held = todos.length;
      replaced.push(todos.map((t) => t.id));
      return 'saved';
    },
  };
  const document = {
    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
    querySelectorAll() { return []; },
    createElement() { return fakeElement(); },
  };
  vm.runInNewContext(appJs, { ...backup, store, document, crypto });
  const dialog = document.querySelector('#confirm');
  const answer = (value) => {
    approved = value === 'yes';
    dialog.close(value);
  };
  const pick = (file) => {
    const input = document.querySelector('#import');
    input.files = [file];
    return input.onchange({ target: input });
  };
  const submit = (value) => {
    document.querySelector('#title').value = value;
    document.querySelector('#add').onsubmit({ preventDefault() {} });
  };
  return { pick, submit, answer, replaced, violations, dialog };
}

test('a big file still being read, then a small one: neither replaces a non-empty list without asking', async () => {
  const { pick, answer, replaced, violations, dialog } = loadApp();
  const big = slowFile([todo('a1'), todo('a2'), todo('a3')]);
  const first = pick(big);
  const second = pick(quickFile([todo('b1')]));
  await settle();
  big.finish();
  await settle();
  // Whichever import ran first filled the empty list; the other one must now ask.
  assert.equal(replaced.length, 1);
  assert.equal(dialog.open, true, 'the second import must ask before replacing the list the first one filled');

  answer('no');
  await Promise.all([first, second]);
  assert.equal(replaced.length, 1, 'cancel keeps the list');
  assert.deepEqual(violations, []);
});

test('a todo added while a file is being read is not replaced without asking', async () => {
  const { pick, submit, answer, replaced, violations, dialog } = loadApp();
  const big = slowFile([todo('a1')]);
  const first = pick(big);
  submit('Mua sữa');

  big.finish();
  await settle();
  assert.equal(dialog.open, true, 'the import must ask: the list is no longer empty');
  assert.deepEqual(replaced, []);

  answer('yes');
  await first;
  assert.deepEqual(replaced, [['a1']], 'agree replaces');
  assert.deepEqual(violations, []);
});

test('two imports over a non-empty list ask one after the other, never two dialogs at once', async () => {
  const { pick, submit, answer, replaced, violations, dialog } = loadApp();
  submit('Mua sữa');
  const big = slowFile([todo('a1')]);
  const first = pick(big);
  const second = pick(quickFile([todo('b1')]));
  await settle();
  big.finish();
  await settle();
  assert.equal(dialog.open, true);

  answer('no');
  await settle();
  assert.equal(dialog.open, true, 'the next import asks once the first dialog is closed');
  answer('yes');
  await Promise.all([first, second]);
  assert.equal(replaced.length, 1);
  assert.deepEqual(violations, []);
});

